  `KiAttack` int unsigned NOT NULL DEFAULT '0',
  `Defence` int unsigned NOT NULL DEFAULT '0',
  `Speed` int unsigned NOT NULL DEFAULT '0',
  `CurrentTransformation` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`UserID`),
  KEY `race` (`Race`) /*!80000 INVISIBLE */,
  KEY `CurrentTransformation` (`CurrentTransformation`) /*!80000 INVISIBLE */,
  CONSTRAINT `CurrentTransformation_FK` FOREIGN KEY (`CurrentTransformation`) REFERENCES `transformations` (`TransformationName`) ON UPDATE CASCADE,
  CONSTRAINT `users_data_TO_races` FOREIGN KEY (`Race`) REFERENCES `races` (`RaceName`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Where we store most of the data of the users';
